import pandas as pd
import numpy as np
import random

DATASET_PATH = 'chunks_csv/changespillover/changespillover_2021_2023_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Load data
df_changes = pd.read_csv(DATASET_PATH)
df_adj = pd.read_csv(ADJACENCY_PATH)

boroughs = df_changes['borough'].unique()
adj_dict = {b: [] for b in boroughs}

# Build adjacency dictionary
for _, row in df_adj.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b in adj_dict:
        adj_dict[b].append(n)

# Prepare delta values and compute mean
delta_values = df_changes.set_index('borough')['delta_value'].to_dict()
x_bar = np.mean(list(delta_values.values()))
deviations = {b: delta_values[b] - x_bar for b in delta_values}

# Compute observed Moran's I
spatial_lag = {}
for b in adj_dict:
    neighbors = adj_dict[b]
    k_i = len(neighbors)
    if k_i == 0:
        spatial_lag[b] = 0.0
    else:
        sum_neighbors = 0.0
        for n in neighbors:
            if n in deviations:
                sum_neighbors += deviations[n] / k_i
        spatial_lag[b] = sum_neighbors

numerator = 0.0
for b in deviations:
    if b in spatial_lag:
        numerator += deviations[b] * spatial_lag[b]

denominator = sum(d**2 for d in deviations.values())
observed_I = numerator / denominator

# Permutation test for significance
n_permutations = 500
permuted_Is = []

original_boroughs = list(df_changes['borough'])
original_deltas = list(df_changes['delta_value'])

for _ in range(n_permutations):
    shuffled_deltas = np.random.permutation(original_deltas)
    delta_values_permuted = dict(zip(original_boroughs, shuffled_deltas))
    x_bar_permuted = np.mean(shuffled_deltas)
    deviations_permuted = {b: delta_values_permuted[b] - x_bar_permuted for b in original_boroughs}

    spatial_lag_permuted = {}
    for b in adj_dict:
        neighbors = adj_dict[b]
        k_i = len(neighbors)
        if k_i == 0:
            spatial_lag_permuted[b] = 0.0
        else:
            sum_neighbors = 0.0
            for n in neighbors:
                if n in deviations_permuted:
                    sum_neighbors += deviations_permuted[n] / k_i
            spatial_lag_permuted[b] = sum_neighbors

    numerator_permuted = 0.0
    for b in original_boroughs:
        if b in spatial_lag_permuted:
            numerator_permuted += deviations_permuted[b] * spatial_lag_permuted[b]

    denominator_permuted = sum(d**2 for d in deviations_permuted.values())
    permuted_I = numerator_permuted / denominator_permuted
    permuted_Is.append(permuted_I)

# Compute p-value
count = sum(1 for pi in permuted_Is if pi >= observed_I)
p_value = (count + 1) / (n_permutations + 1)

# Determine final answer
if p_value < 0.05:
    print(f"FINAL ANSWER: CLUSTERED (test statistic = {observed_I}, p = {p_value})")
else:
    print(f"FINAL ANSWER: NOT CLUSTERED (test statistic = {observed_I}, p = {p_value})")
